function CreativeUniverseSection(){
 const worlds=[{name:'Writing',icon:'✍',focus:'Writing & ideas'},{name:'Images',icon:'◈',focus:'Images & design'},{name:'Video',icon:'▶',focus:'Motion & video'},{name:'Agents',icon:'✳',focus:'Agents & automation'},{name:'Voice',icon:'◖',focus:'Voice & sound'}];
 const [active,setActive]=useState<number|null>(null);
 return <section id="creative-universe" className="section creative-universe-section" aria-labelledby="creative-universe-heading"><div className="shell">
  <SectionEyebrow>SECTION 02 / THE CREATIVE UNIVERSE</SectionEyebrow>
  <div className="cu-intro"><h2 id="creative-universe-heading">One space.<br/><span>Infinite ways</span><br/>to create.</h2><p>Ideas don’t belong in boxes. Neither should your tools. Discover a universe where imagination, intelligence, and creativity come together in one extraordinary workspace.</p></div>
  <div className="cu-universe"><span className="cu-status">XNOVAH / CREATIVE ECOSYSTEM</span><div className="cu-ring cu-ring-one"/><div className="cu-ring cu-ring-two"/><div className="cu-core" aria-hidden="true">✳</div>{worlds.map((w,i)=><button key={w.name} type="button" aria-pressed={active===i} onClick={()=>setActive(i)} className={'cu-orbit cu-orbit-'+(i+1)+(active===i?' selected':'')}>{w.icon} {w.name}</button>)}<span className="cu-hint">SELECT A CREATIVE WORLD ↗</span></div>
  <p className="cu-focus" aria-live="polite">{active===null?'Five creative worlds. One Xnovah universe.':worlds[active].focus+' — part of your Xnovah creative universe.'}</p>
  <div className="cu-pillars"><article><span>01 / IMAGINE</span><h3>Think without limits.</h3><p>Go from a fleeting thought to a powerful concept. Discover new perspectives and creative directions.</p></article><article><span>02 / CREATE</span><h3>Bring ideas to life.</h3><p>Explore stories, images, motion, audio, and digital experiences in a connected creative space.</p></article><article><span>03 / BUILD</span><h3>Make possibility real.</h3><p>Turn inspiration into projects, workflows, and experiences worth sharing with the world.</p></article></div>
  <div className="cu-footer"><span>✳ XNOVAH AI — A new creative universe is taking shape.</span><a href="#feature-universe">UP NEXT / SECTION 03 — 39 AI FEATURES ↗</a></div>
 </div></section>
}

function FeatureUniverse(){const [current,setCurrent]=useState(0);const [filter,setFilter]=useState('All');const [search,setSearch]=useState('');const [showDirectory,setShowDirectory]=useState(false);const indexes=allToolNames.map((_,i)=>i).filter(i=>(filter==='All'||toolTypes[i]===filter)&&allToolNames[i].toLowerCase().includes(search.toLowerCase()));const active=indexes.includes(current)?current:indexes[0]??0;const move=(n:number)=>{if(!indexes.length)return;setCurrent(indexes[(Math.max(0,indexes.indexOf(active))+n+indexes.length)%indexes.length])};return <section className="section feature-universe" id="feature-universe"><div className="shell"><div className="feature-heading"><SectionEyebrow>THE XNOVAH CREATIVE UNIVERSE</SectionEyebrow><h2>One universe. <span className="gradient-text">Endless possibilities.</span></h2><p>Explore 39 distinct creative experiences. Every tool has its own place in the universe — and its own story to tell.</p></div><div className="feature-carousel" aria-label="39 AI feature slider"><div className="feature-carousel-copy"><div className="feature-index">{String(active+1).padStart(2,'0')} / 39 &nbsp; · &nbsp; {toolTypes[active]}</div><h3>{allToolNames[active]}</h3><p>Explore what becomes possible with {allToolNames[active].toLowerCase()} — a dedicated experience within the Xnovah creative workspace.</p><div className="feature-actions"><a href="#tools" className="feature-explore">Explore creative tools <ArrowUpRight size={17}/></a><span>CONCEPT PREVIEW</span></div></div><div className="feature-carousel-visual" aria-label={'Image placeholder for '+allToolNames[active]}><div className="feature-placeholder-halo"/><div className="feature-placeholder-glyph">{toolGlyphs[active]}</div><div className="feature-placeholder-caption">CUSTOM ARTWORK COMING SOON <span>✳</span></div></div><div className="feature-carousel-bottom"><div className="feature-carousel-progress"><div style={{width:`${(active+1)/39*100}%`}}/></div><div className="feature-carousel-controls"><button onClick={()=>move(-1)} aria-label="Previous AI feature">←</button><span>{String(active+1).padStart(2,'0')} / 39</span><button onClick={()=>move(1)} aria-label="Next AI feature">→</button></div></div></div><div className="feature-directory-bar"><div className="feature-category-pills">{['All','Agents','Visual','Video','Audio','Writing','Business','Workspace','Chat','Code','Research'].map(cat=><button className={filter===cat?'active':''} key={cat} onClick={()=>{setFilter(cat);setShowDirectory(true)}}>{cat==='All'?'All tools':cat}</button>)}</div><button className="feature-directory-toggle" onClick={()=>setShowDirectory(!showDirectory)} aria-expanded={showDirectory}>{showDirectory?'Hide tool directory':'Browse all 39 tools'} <ChevronDown size={15}/></button></div>{showDirectory&&<div className="feature-directory"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search tools..." aria-label="Search tools"/><div className="feature-directory-grid">{indexes.map(i=><button key={i} onClick={()=>{setCurrent(i);document.getElementById('feature-universe')?.scrollIntoView({behavior:'smooth'})}}><span>{toolGlyphs[i]}</span><b>{allToolNames[i]}</b><small>{toolTypes[i]}</small></button>)}</div>{!indexes.length&&<p>No matching tools.</p>}</div>}<p className="feature-disclaimer">Visual placeholders are intentional. Final artwork will be generated and reviewed one feature at a time. The tools shown represent planned capabilities, not verified live services.</p></div></section>}
const audiences=['Content creators','Entrepreneurs','Marketing teams','Social media managers','Designers','Writers & bloggers','Developers','E-commerce sellers','Agencies','Educators','Students','Researchers','Podcasters','Video creators','Small businesses'];
function AudienceUniverse(){const [active,setActive]=useState(0);return <section className="section extra-section audience-universe" id="audiences"><div className="shell"><SectionEyebrow>MADE FOR THE WAY YOU WORK</SectionEyebrow><h2>Fifteen ways to start.<br/><span className="gradient-text">Infinite ways to grow.</span></h2><p className="extra-lead">From independent creators to ambitious teams, there's room for every kind of imagination.</p><div className="audience-explorer"><div className="audience-options">{audiences.map((a,i)=><button key={a} onClick={()=>setActive(i)} className={i===active?'active':''}>{String(i+1).padStart(2,'0')} &nbsp; {a}</button>)}</div><div className="audience-feature"><span>YOUR CREATIVE WORLD / {String(active+1).padStart(2,'0')}</span><div className="audience-feature-art">✳</div><h3>Built for {audiences[active].toLowerCase()}.</h3><p>Explore creative workflows, fresh ideas and ways to move from inspiration to execution in one connected space.</p><a href="#waitlist">Join the early-access list ↗</a></div></div></div></section>}
const templates=[['Marketing','Campaign brief','Ad headlines','Product descriptions','Email sequence','Brand voice'],['Social','Instagram captions','LinkedIn post','Video hooks','Content calendar','Hashtags'],['Writing','Blog outline','Article draft','Story starter','Rewrite & refine','Newsletter'],['Business','Business plan','Sales pitch','Customer reply','Meeting recap','Proposal'],['Creative','Video script','Image prompts','Character concepts','Creative brief','Podcast outline'],['Learning','Study guide','Lesson plan','Research summary','Quiz questions','Explainer']];
function TemplateLibrary(){const [cat,setCat]=useState('All');const [search,setSearch]=useState('');const rows=templates.flatMap(([group,...items])=>items.map(name=>({group,name}))).filter(t=>(cat==='All'||t.group===cat)&&t.name.toLowerCase().includes(search.toLowerCase()));return <section className="section extra-section template-universe" id="templates"><div className="shell"><SectionEyebrow>YOUR NEXT STARTING POINT</SectionEyebrow><h2>A template for <span className="gradient-text">almost anything.</span></h2><p className="extra-lead">Explore creative starting points across marketing, social, business, writing and more.</p><div className="template-controls"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search creative templates..." aria-label="Search templates"/><div>{['All',...templates.map(t=>t[0])].map(c=><button className={cat===c?'active':''} onClick={()=>setCat(c)} key={c}>{c}</button>)}</div></div><div className="template-grid">{rows.map(t=><div className="template-card" key={t.group+t.name}><span>✳ &nbsp; {t.group.toUpperCase()}</span><h3>{t.name}</h3><p>A thoughtful first step for your next creative workflow.</p><small>WORKFLOW CONCEPT ↗</small></div>)}</div>{rows.length===0&&<p>No templates match that search.</p>}</div></section>}
function PlatformWalkthrough(){const [step,setStep]=useState(0);const stages=[['Start with a spark','Bring a brief, an image, a question or a rough idea.'],['Choose your creative direction','Explore writing, visuals, research, audio or another dedicated experience.'],['Shape what comes next','Refine the concept and make it your own.']];return <section className="section extra-section walkthrough" id="walkthrough"><div className="shell"><SectionEyebrow>SEE XNOVAH IN ACTION</SectionEyebrow><h2>A better flow from <span className="gradient-text">idea to output.</span></h2><p className="extra-lead">A conceptual walkthrough of how the connected workspace is intended to feel.</p><div className="walkthrough-layout"><div className="walkthrough-menu">{stages.map((s,i)=><button className={i===step?'active':''} onClick={()=>setStep(i)} key={s[0]}><span>0{i+1}</span><b>{s[0]}</b><small>{s[1]}</small></button>)}</div><div className="walkthrough-display"><span>✳ &nbsp; XNOVAH / WORKFLOW CONCEPT</span><div className="walkthrough-center"><div className="walkthrough-symbol">{['✧','◈','✳'][step]}</div><h3>{stages[step][0]}</h3><p>{stages[step][1]}</p></div><div className="walkthrough-meter"><i style={{width:`${(step+1)*100/3}%`}}/></div></div></div></div></section>}
function IntegrationUniverse(){return <section className="section extra-section integration-universe" id="integrations"><div className="shell"><SectionEyebrow>WORK WHERE YOUR IDEAS LIVE</SectionEyebrow><h2>Connected by <span className="gradient-text">possibility.</span></h2><p className="extra-lead">A vision for more connected workflows — from creative projects to the places where you publish, collaborate and share.</p><div className="integration-diagram"><div className="integration-core">✳<b>XNOVAH</b></div>{['Content platforms','Creative tools','Communication','Business workflows','Files & knowledge','Publishing'].map((x,i)=><div className={'integration-node integration-node-'+i} key={x}><span>✦</span>{x}</div>)}</div><p className="feature-disclaimer">Illustrative integration categories only. No third-party connection is confirmed until configured and tested.</p></div></section>}
function CompareWays(){return <section className="section extra-section compare-universe" id="comparison"><div className="shell"><SectionEyebrow>WHY ONE WORKSPACE</SectionEyebrow><h2>Less switching. <span className="gradient-text">More creating.</span></h2><p className="extra-lead">A comparison of workflow approaches, not a claim about specific subscription prices or guaranteed capabilities.</p><div className="comparison-table"><div className="comparison-row heading"><span>WORKFLOW</span><b>Separate tools</b><b>Xnovah vision</b></div>{[['Finding the right workflow','Switch between different apps','Discover experiences in one place'],['Creative context','Move information between tools','Explore a connected creative journey'],['Learning new tools','Multiple interfaces to navigate','A more cohesive design language'],['Expanding possibilities','Piece together a personal stack','Discover new capabilities as they launch']].map(row=><div className="comparison-row" key={row[0]}><strong>{row[0]}</strong><span>{row[1]}</span><span>{row[2]}</span></div>)}</div></div></section>}
function ConceptGallery(){return <section className="section extra-section gallery-universe" id="gallery"><div className="shell"><SectionEyebrow>WHAT PEOPLE COULD BUILD</SectionEyebrow><h2>One idea. <span className="gradient-text">A thousand directions.</span></h2><p className="extra-lead">Illustrative project concepts, not customer testimonials or examples of real outputs from a live product.</p><div className="gallery-grid">{[['Brand worlds','A distinctive visual identity for an ambitious new idea.','✦'],['Campaign stories','A creative launch concept told across formats.','◈'],['Product moments','Beautiful scenes that give products their own spotlight.','✳'],['Creative presentations','A pitch that turns information into a story.','▧']].map((g,i)=><article className={'gallery-card gallery-'+i} key={g[0]}><div className="gallery-art">{g[2]}</div><div><span>CONCEPT 0{i+1}</span><h3>{g[0]}</h3><p>{g[1]}</p></div></article>)}</div></div></section>}
function MidCTA({title,subtitle}:{title:string,subtitle:string}){return <section className="section mid-cta"><div className="shell mid-cta-inner"><span>✳ &nbsp; YOUR NEXT IDEA STARTS HERE</span><h2>{title}</h2><p>{subtitle}</p><a href="#waitlist">Get early access <ArrowUpRight size={18}/></a></div></section>}
function Newsletter(){return <section className="section extra-section newsletter-universe" id="newsletter"><div className="shell newsletter-layout"><div><SectionEyebrow>THE XNOVAH DISPATCH</SectionEyebrow><h2>Good things are <span className="gradient-text">taking shape.</span></h2><p>Product reveals, creative inspiration and launch updates, delivered when there's something worth sharing.</p></div><WaitlistForm compact/></div></section>}

function DedicatedShowcases(){const [selected,setSelected]=useState<number|null>(null);return <div className="dedicated-wrap" id="tools"><div className="shell"><div className="dedicated-intro"><SectionEyebrow>EXPLORE YOUR CREATIVE UNIVERSE</SectionEyebrow><h2>Every possibility deserves <span className="gradient-text">its own spotlight.</span></h2><p>Discover the individual creative experiences we're exploring for Xnovah. Each showcase is a concept preview, not a live AI generation tool.</p></div></div>{dedicatedFeatures.map((item,index)=><section className={'dedicated-section dedicated-theme-'+index%4} id={'tool-'+index} key={item.name}><div className="shell dedicated-grid"><div className="dedicated-copy"><span className="dedicated-number">XNOVAH / {String(index+1).padStart(2,'0')} — CREATIVE CAPABILITIES</span><h2>{item.title}</h2><p>{item.description}</p><div className="dedicated-label">{item.name}</div><div className="dedicated-steps">{item.steps.split(' · ').map(step=><span key={step}>{step}</span>)}</div><div className="dedicated-actions"><button type="button" className="button-ghost dedicated-preview-btn" onClick={()=>setSelected(selected===index?null:index)} aria-expanded={selected===index}>{selected===index?'Hide preview':'Explore concept'} <ArrowUpRight size={16}/></button><a href="#waitlist" className="dedicated-link">Get early access ↗</a></div>{selected===index&&<div className="dedicated-detail"><b>Experience concept</b><p>{item.sample} This is a visual illustration; no AI request is being made.</p></div>}</div><div className="dedicated-visual" aria-label={item.name+' concept illustration'}><div className="dedicated-visual-grid"/><div className="dedicated-visual-orb"/><div className="dedicated-glass-card"><span className="dedicated-card-top"><span>✳ XNOVAH STUDIO</span><span>CONCEPT / {String(index+1).padStart(2,'0')}</span></span><div className="dedicated-card-icon">✦</div><span className="dedicated-card-type">{item.name.toUpperCase()}</span><strong>{item.sample}</strong><div className="dedicated-card-bottom"><span>✧ CREATIVE MODE</span><span>↗</span></div></div><span className="dedicated-visual-caption">IMAGINE MORE / CREATE BEYOND</span></div></div></section>)}</div>}
function LaunchRoadmap(){return <section className="section roadmap-section" id="roadmap"><div className="shell"><div className="section-intro centered"><SectionEyebrow>THE JOURNEY AHEAD</SectionEyebrow><h2>Something extraordinary <span className="gradient-text">is taking shape.</span></h2><p>We're building toward a connected creative experience. Milestones below describe our direction, not confirmed release dates.</p></div><div className="roadmap-grid">{[{n:'01',name:'The first spark',phase:'PRELAUNCH',desc:'Shape the experience, refine the product vision and welcome our earliest supporters.'},{n:'02',name:'Open the doors',phase:'EARLY ACCESS',desc:'Invite initial users to explore available tools and help guide what comes next.'},{n:'03',name:'Create beyond',phase:'EVOLVING PLATFORM',desc:'Keep expanding the creative universe as integrations and capabilities are validated.'}].map(r=><article className="roadmap-card" key={r.n}><span>{r.n} / {r.phase}</span><h3>{r.name}</h3><p>{r.desc}</p></article>)}</div></div></section>}


